function log(t,c){const d=document.createElement('div');d.textContent=t;if(c)d.style.borderColor=c;const L=$('log');L.prepend(d);while(L.children.length>6)L.lastChild.remove();setTimeout(()=>d.style.opacity=0,6000);setTimeout(()=>d.remove(),7200)}
let toastT;function toast(t){const e=$('toast');e.textContent=t;e.style.display='block';clearTimeout(toastT);toastT=setTimeout(()=>e.style.display='none',3500)}
function setBar(id,v){$(id).querySelector('i').style.width=clamp(v,0,100)+'%'}
