let AC=null,master,hum,sirenOsc,sirenGain;
function initAudio(){if(AC)return;try{AC=new (window.AudioContext||window.webkitAudioContext)();master=AC.createGain();master.gain.value=.5;master.connect(AC.destination);
const o=AC.createOscillator();o.type='sawtooth';o.frequency.value=50;const f=AC.createBiquadFilter();f.type='lowpass';f.frequency.value=140;hum=AC.createGain();hum.gain.value=.06;o.connect(f);f.connect(hum);hum.connect(master);o.start();
sirenOsc=AC.createOscillator();sirenOsc.type='square';sirenOsc.frequency.value=440;sirenGain=AC.createGain();sirenGain.gain.value=0;const sf=AC.createBiquadFilter();sf.type='bandpass';sf.frequency.value=700;sirenOsc.connect(sf);sf.connect(sirenGain);sirenGain.connect(master);sirenOsc.start();}catch(e){}}
function noise(dur,vol,freq,type){if(!AC)return;const n=AC.sampleRate*dur,b=AC.createBuffer(1,n,AC.sampleRate),d=b.getChannelData(0);for(let i=0;i<n;i++)d[i]=(Math.random()*2-1)*Math.pow(1-i/n,2);const s=AC.createBufferSource();s.buffer=b;const f=AC.createBiquadFilter();f.type=type||'lowpass';f.frequency.value=freq||1200;const g=AC.createGain();g.gain.value=vol;s.connect(f);f.connect(g);g.connect(master);s.start()}
function tone(fr,dur,vol,type){if(!AC)return;const o=AC.createOscillator(),g=AC.createGain();o.type=type||'sine';o.frequency.value=fr;g.gain.setValueAtTime(vol,AC.currentTime);g.gain.exponentialRampToValueAtTime(.0001,AC.currentTime+dur);o.connect(g);g.connect(master);o.start();o.stop(AC.currentTime+dur)}
const SFX={shot(){noise(.25,.9,2500);tone(90,.2,.5,'square')},step(){noise(.06,.12,500)},door(){noise(.5,.25,300);tone(70,.4,.2,'sawtooth')},kick(){noise(.15,.6,400)},click(){tone(1200,.05,.15,'square')},hurt(){tone(160,.3,.3,'sawtooth')},growl(){const o=AC&&AC.createOscillator();if(!o)return;const g=AC.createGain();o.type='sawtooth';o.frequency.setValueAtTime(70,AC.currentTime);o.frequency.linearRampToValueAtTime(40,AC.currentTime+1.2);g.gain.setValueAtTime(.3,AC.currentTime);g.gain.linearRampToValueAtTime(0,AC.currentTime+1.2);o.connect(g);g.connect(master);o.start();o.stop(AC.currentTime+1.3)},drink(){for(let i=0;i<3;i++)setTimeout(()=>tone(300+Math.random()*100,.1,.15),i*180)},pickup(){tone(660,.1,.15);setTimeout(()=>tone(990,.12,.12),90)}};
