TX.parquet=T(512,512,(x,w,h)=>{for(let j=0;j<16;j++)for(let i=0;i<8;i++){const v=ri(-15,15),off=j%2?32:0;x.fillStyle='rgb('+(140+v)+','+(90+v)+','+(50+v)+')';x.fillRect(i*64+off-64,j*32,64,32);x.fillRect(i*64+off,j*32,64,32);x.strokeStyle='rgba(40,20,5,.6)';x.strokeRect(i*64+off,j*32,64,32);for(let k=0;k<4;k++){x.strokeStyle='rgba(60,30,10,.2)';x.beginPath();const yy=j*32+rnd(4,28);x.moveTo(i*64+off,yy);x.lineTo(i*64+off+64,yy+rnd(-2,2));x.stroke()}}blot(x,w,h,15,'rgba(0,0,0,.25)',10,60);blot(x,w,h,8,'rgba(255,230,190,.08)',30,100);nz(x,w,h,12)});
