function walk(x,z){const r=.28;let ok=false;const ax=Math.abs(x),sx=Math.sign(x);
if(ax<=2-r&&z<=18-r&&z>=-18+r)ok=true;
if(!ok&&!cur.gateClosed&&ax<=1.2-r&&z<-17.5&&z>-26.6)ok=true;
if(!ok&&cur.upOpen&&ax<=1.2-r&&z<=18.6&&z>=17)ok=true;
if(!ok)for(const d of cur.doors){if(sx!==d.side)continue;if(d.open&&Math.abs(z-d.z)<=.35&&ax>=1.5&&ax<=2.5){ok=true;break}if(ax>=2+r&&ax<=8-r&&Math.abs(z-d.z)<=3-r){ok=true;break}}
if(!ok)return false;for(const c of colliders)if(x>c.x1-r&&x<c.x2+r&&z>c.z1-r&&z<c.z2+r)return false;return true}
function roomOf(x,z){const ax=Math.abs(x);if(ax<2.05)return null;for(const d of cur.doors)if(Math.sign(x)===d.side&&Math.abs(z-d.z)<3)return d;return null}
