drink(){if(G.bottles<=0)return log('Воды нет.');if(G.water>97)return log('Пить не хочется.');G.bottles--;G.water=Math.min(100,G.water+35);SFX.drink();stats.drinks++;saveStats();if(stats.drinks>=50)unlock('drinker');log('Глоток воды. Ржавая, но живая.')},
