cout=function(t,cls){const d=document.createElement('div');d.className='l '+(cls||'');d.innerHTML='<span class="t">'+ts()+'</span>';d.appendChild(document.createTextNode(t));out.appendChild(d);while(out.children.length>300)out.firstChild.remove();out.scrollTop=1e9};
