function matches(){const v=inp.value.trim().split(/\s+/)[0]||'';if(!v||inp.value.includes(' '))return[];return Object.keys(CMDS).filter(k=>k.startsWith(v.toLowerCase()))}
function showSug(){const m=matches();if(!m.length){sug.style.display='none';return}sel=Math.min(sel,m.length-1);sug.innerHTML=m.map((k,i)=>'<div class="'+(i===sel?'sel':'')+'" data-k="'+k+'"><b>'+k+'</b><i>'+CMDS[k]+'</i></div>').join('');sug.style.display='block';sug.querySelectorAll('[data-k]').forEach(e=>e.onmousedown=ev=>{ev.preventDefault();inp.value=e.dataset.k+' ';showSug()})}
inp.addEventListener('input',()=>{sel=-1;showSug()});
inp.addEventListener('keydown',e=>{const m=matches();if(e.code==='Tab'){e.preventDefault();if(m.length){inp.value=m[Math.max(0,sel)]+' ';sel=-1;showSug()}return}
if(e.code==='ArrowDown'&&m.length){e.preventDefault();sel=(sel+1)%m.length;showSug();return}if(e.code==='ArrowUp'&&m.length&&sel>=0){e.preventDefault();sel--;showSug();return}
if(e.code==='ArrowUp'){e.preventDefault();if(hi>0){hi--;inp.value=hist[hi]||''}return}if(e.code==='ArrowDown'){e.preventDefault();if(hi<hist.length){hi++;inp.value=hist[hi]||''}return}
if(e.code==='Enter'){e.stopImmediatePropagation();e.preventDefault();if(sel>=0&&m.length){inp.value=m[sel]+' ';sel=-1;showSug();return}const v=inp.value;inp.value='';sug.style.display='none';exec(v)}},true);
toggleConsole=function(){conOpen=!conOpen;C.classList.toggle('open',conOpen);if(conOpen){document.exitPointerLock&&document.exitPointerLock();setTimeout(()=>inp.focus(),60)}else{inp.blur();sug.style.display='none';if(G&&G.state==='play')lockPointer()}};
setInterval(()=>{if(!conOpen)return;const on=!!(G&&G.state);$('cFl').textContent=on?'ЭТАЖ '+G.floor:'МЕНЮ';$('cPh').textContent=on?({calm:'НОРМА',warn:'СИРЕНА',gas:'ГАЗ'}[G.phase]||'—'):'—';$('cPh').className='chip'+(on&&G.phase!=='calm'?' bad':'');$('cHp').textContent=on?'HP '+Math.round(G.hp):'HP —';$('cGod').className='chip'+(on&&G.god?' on':'');$('cFps').className='chip'+(fpsOn?' on':'')},250);
